import React from 'react';
import { BanknotesIcon, WalletIcon } from '@heroicons/react/24/outline';

const FinancialInputs = ({ income, setIncome, currentSavings, setCurrentSavings }) => {
  return (
    <div className="flex items-center gap-4">
      <div className="flex items-center gap-2 bg-gradient-to-r from-blue-50 to-blue-100 px-4 py-2 rounded-lg shadow-sm">
        <BanknotesIcon className="h-5 w-5 text-blue-600" />
        <div className="flex flex-col">
          <label className="text-xs font-medium text-blue-900">Monthly Income</label>
          <div className="flex items-center gap-1">
            <span className="text-sm text-blue-900">$</span>
            <input
              type="number"
              min="0"
              className="w-32 px-2 py-1 rounded border border-blue-200 focus:outline-none focus:ring-2 focus:ring-blue-500 text-right bg-white text-blue-900"
              value={income}
              onChange={e => setIncome(Number(e.target.value))}
              placeholder="0.00"
            />
          </div>
        </div>
      </div>

      <div className="flex items-center gap-2 bg-gradient-to-r from-emerald-50 to-emerald-100 px-4 py-2 rounded-lg shadow-sm">
        <WalletIcon className="h-5 w-5 text-emerald-600" />
        <div className="flex flex-col">
          <label className="text-xs font-medium text-emerald-900">Total Savings</label>
          <div className="flex items-center gap-1">
            <span className="text-sm text-emerald-900">$</span>
            <input
              type="number"
              min="0"
              className="w-32 px-2 py-1 rounded border border-emerald-200 focus:outline-none focus:ring-2 focus:ring-emerald-500 text-right bg-white text-emerald-900"
              value={currentSavings}
              onChange={e => setCurrentSavings(Number(e.target.value))}
              placeholder="0.00"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default FinancialInputs;
